import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';

/**
 * The provider capsules, discovered the way the node capsules are: one folder, one manifest, and
 * three generated files nobody edits. Before this, adding a provider meant touching a hand-written
 * descriptor list, a hand-written install list and the global dictionary, and nothing checked that
 * the three agreed with the provider's own schema.
 *
 * The split matters as much as the discovery. A provider's `index.ts` spawns processes and reads
 * files, so the browser must never load it; its `settings.ts` is plain Zod, so the browser can draw
 * the form from the very schema the server validates against.
 */

const root = process.cwd();
const providersDir = path.join(root, 'capsules', 'providers');
const generatedDir = path.join(providersDir, '.generated');
const folders = (await readdir(providersDir, { withFileTypes: true }))
  .filter((entry) => entry.isDirectory() && !entry.name.startsWith('.') && !entry.name.startsWith('_'))
  .map((entry) => entry.name)
  .sort();

const capsules = [];
for (const folder of folders) {
  const file = path.join(providersDir, folder, 'provider.manifest.json');
  let manifest;
  try { manifest = JSON.parse(await readFile(file, 'utf8')); }
  catch (error) {
    if (error?.code === 'ENOENT') continue;
    throw new Error(`${path.relative(root, file)}: ${error.message}`);
  }
  capsules.push({ folder, ...manifest });
}

const ids = new Set();
for (const item of capsules) {
  for (const key of ['id', 'kind', 'register', 'settings', 'widgets', 'translations']) {
    if (typeof item[key] !== 'string' || !item[key]) throw new Error(`${item.folder}/provider.manifest.json: ${key} is required`);
  }
  if (item.kind !== 'tts' && item.kind !== 'llm') throw new Error(`${item.folder}/provider.manifest.json: kind must be "tts" or "llm"`);
  if (ids.has(item.id)) throw new Error(`duplicate provider id: ${item.id}`);
  ids.add(item.id);
}

// Client-safe: the schemas and nothing that touches the machine.
const descriptors = `/* Generated by scripts/discover-providers.mjs. Do not edit. */
import { defaultSettingsOf } from '@/contracts/providers/registry';
import { schemaFields } from '@/core/schema-form';
import type { ProviderDescriptor } from '../installed';
${capsules.map((item) => `import { ${item.settings}, ${item.widgets} } from '../${item.folder}/settings';`).join('\n')}

/**
 * Every provider this build ships, described from its own schema. The fields the node draws, the
 * settings a fresh node starts with and the rules the server validates against are one thing seen
 * three ways, so they cannot disagree.
 */
export const PROVIDERS: ProviderDescriptor[] = [
${capsules.map((item) => `  { id: '${item.id}', kind: '${item.kind}', nameKey: 'provider.${item.id}', noteKey: 'provider.${item.id}.note', settingsSchema: ${item.settings}, defaultSettings: defaultSettingsOf(${item.settings}), fields: schemaFields(${item.settings}), widgets: ${item.widgets} },`).join('\n')}
];
`;

// Server only: these modules spawn processes and read the filesystem.
const server = `/* Generated by scripts/discover-providers.mjs. Do not edit. Server only. */
${capsules.map((item) => `import { ${item.register} } from '../${item.folder}';`).join('\n')}

/** Every provider factory, registered once. Each registration is a Map.set: setting it twice is setting it once. */
export function installProviders(): void {
${capsules.map((item) => `  ${item.register}();`).join('\n')}
}
`;

const locales = `/* Generated by scripts/discover-providers.mjs. Do not edit. */
${capsules.map((item) => `import { ${item.translations} } from '../${item.folder}/locales';`).join('\n')}

/** Every string a provider shows: its name, the line under the picker, and its own value labels. */
export const PROVIDER_TRANSLATIONS: Record<string, Record<string, string>> = { en: {}, vi: {} };
for (const extension of [${capsules.map((item) => item.translations).join(', ')}]) {
  Object.assign(PROVIDER_TRANSLATIONS.en!, extension.en);
  Object.assign(PROVIDER_TRANSLATIONS.vi!, extension.vi);
}
`;

await mkdir(generatedDir, { recursive: true });
await Promise.all([
  writeFile(path.join(generatedDir, 'descriptors.ts'), descriptors),
  writeFile(path.join(generatedDir, 'server.ts'), server),
  writeFile(path.join(generatedDir, 'locales.ts'), locales),
]);
console.log(`Discovered ${capsules.length} provider capsules.`);
